#nullable enable
using Marten;
using Spend.Contracts;
using Wolverine.Http;

namespace Spend.Slices.Spend;

/// <summary>
/// Sets or raises a department's budget. No rules: the model's two GWTs are "a budget is set" and "the
/// budget may be raised at any time", so the latest value simply wins.
///
/// <c>FetchForWriting</c> rather than a bare append, even with nothing to decide. It costs nothing here
/// and it is what makes "the budget may be raised" safe under two concurrent raises: the stream's version
/// is checked, so one of them loses rather than both silently succeeding in an undefined order.
///
/// NOTE THIS SLICE NO LONGER CREATES A GUARD ROW. An earlier version of this folder needed one for the
/// hand-rolled guard-row mechanism — and needed it created HERE, because Marten's Store() is an upsert and
/// a guard created lazily by the first racing writer protects nothing. The production decider now uses DCB,
/// where Marten maintains the version row itself, so there is nothing for this slice to pre-create. The
/// guard-row arm still exists in Concurrency/CommitMechanisms.cs, where its test creates its own row.
/// </summary>
public static class SetBudgetEndpoint
{
    public const string Route = "/departments/{departmentId}/budget";

    [WolverinePost(Route)]
    public static async Task<IResult> Set(Guid departmentId, SetBudget command, IDocumentSession session)
    {
        var stream = await session.Events.FetchForWriting<SetBudgetState>(departmentId);
        stream.AppendOne(new DepartmentBudgetSet(departmentId, command.Budget));

        // AutoApplyTransactions() commits. Returning NoContent rather than the event: an event returned
        // from a Wolverine endpoint is a CASCADING MESSAGE, not a response body.
        return Results.NoContent();
    }
}
